/// A singleton representing the absence of tools for a prompt template.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct NoTools;

/// Constant representing the absence of tools.
pub const NO_TOOLS: NoTools = NoTools;

/// Function pointer type for executing a tool call asynchronously.
pub type ExecuteToolCallFn<E> = for<'a> fn(
  &'a ToolCall,
  &'a E,
) -> std::pin::Pin<
  Box<
    dyn std::future::Future<
        Output = Result<ToolCallResponse, Box<dyn std::error::Error + Send + Sync>>,
      > + Send
      + 'a,
  >,
>;

/// A fully resolved prompt ready to be sent to an LLM.
///
/// The `Output` type parameter is the parsed response type for the template.
/// The `ToolExecutor` type parameter is the type whose methods implement the
/// template's tools, or `NoTools` when no tools are available.
///
/// Build and send the API request using `system_message`, `user_message`,
/// `examples`, and `tools`. If the model requests tool calls, dispatch
/// them with `execute_tools` and then parse the final response with `parse_response`.
pub struct Prompt<Output, ToolExecutor: ?Sized = NoTools> {
  /// Metadata associated with this prompt.
  pub meta: Meta,
  /// The resolved system message.
  pub system_message: String,
  /// The resolved user message.
  pub user_message: String,
  /// Few-shot examples for this prompt.
  pub examples: Vec<FewShotExample>,
  /// The tools available for this prompt, keyed by tool name.
  pub tools: std::collections::HashMap<String, Tool>,
  /// The expected output format.
  pub output_format: OutputFormat,
  /// The identifier of the template from which this prompt was rendered.
  pub template_id: TemplateId,
  pub(crate) execute_tool_call: Option<ExecuteToolCallFn<ToolExecutor>>,
  pub(crate) _phantom: std::marker::PhantomData<fn() -> (Output, ToolExecutor)>,
}

impl<Output, ToolExecutor: ?Sized> Prompt<Output, ToolExecutor> {
  /// Parses the raw LLM response string into the typed output.
  pub fn parse_response(
    &self,
    response: &str,
  ) -> Result<Output, Box<dyn std::error::Error + Send + Sync>>
  where
    Output: serde::de::DeserializeOwned,
  {
    do_parse_response(&self.output_format, &self.template_id, response)
  }

  /// Executes the provided tool calls concurrently using the given tool executor.
  pub async fn execute_tools(
    &self,
    tool_calls: &[ToolCall],
    tool_executor: &ToolExecutor,
  ) -> Result<Vec<ToolCallResponse>, Box<dyn std::error::Error + Send + Sync>> {
    let execute_fn = self.execute_tool_call.ok_or_else(|| {
      Box::<dyn std::error::Error + Send + Sync>::from("This prompt has no tools")
    })?;
    let mut futures = Vec::new();
    for tool_call in tool_calls {
      futures.push(execute_fn(tool_call, tool_executor));
    }
    let mut responses = Vec::with_capacity(futures.len());
    for fut in futures {
      responses.push(fut.await?);
    }
    Ok(responses)
  }
}

