// <static:rust-logic>
fn indent(text: &str, spaces: &str) -> String {
  if spaces.is_empty() {
    return text.to_string();
  }
  text.replace('\n', &format!("\n{}", spaces))
}

fn evaluate(expr: &spec::Expression, val: &serde_json::Value) -> serde_json::Value {
  match expr {
    spec::Expression::KindInput(_) => val.clone(),
    spec::Expression::KindProperty(p) => {
      let left = evaluate(&p.left, val);
      match left {
        serde_json::Value::Object(map) => {
          map.get(&p.property).cloned().unwrap_or(serde_json::Value::Null)
        }
        _ => serde_json::Value::Null,
      }
    }
  }
}

fn format_table(val: &serde_json::Value, fmt: &spec::InsertFormat) -> String {
  let list = match val {
    serde_json::Value::Array(arr) => arr,
    _ => return String::new(),
  };
  if list.is_empty() {
    return String::new();
  }
  let separator = if matches!(fmt, spec::InsertFormat::Csv) { "," } else { "\t" };
  let first_row = match &list[0] {
    serde_json::Value::Object(map) => map,
    _ => return String::new(),
  };
  let headers: Vec<String> = first_row
    .keys()
    .filter(|k| *k != "__keys__")
    .cloned()
    .collect();
  let mut lines = vec![headers.join(separator)];
  for item in list {
    let row = match item {
      serde_json::Value::Object(map) => map,
      _ => continue,
    };
    let mut cells = Vec::new();
    for key in &headers {
      let cell_val = row.get(key);
      let str_val = match cell_val {
        Some(serde_json::Value::String(s)) => s.clone(),
        Some(serde_json::Value::Number(n)) => n.to_string(),
        Some(serde_json::Value::Bool(b)) => b.to_string(),
        Some(serde_json::Value::Null) | None => String::new(),
        Some(other) => other.to_string(),
      };
      if matches!(fmt, spec::InsertFormat::Csv) {
        if str_val.contains('"')
          || str_val.contains(',')
          || str_val.contains('\n')
          || str_val.contains('\r')
        {
          let escaped = str_val.replace('"', "\"\"");
          cells.push(format!("\"{}\"", escaped));
        } else {
          cells.push(str_val);
        }
      } else {
        let escaped = str_val
          .replace('\\', "\\\\")
          .replace('\t', "\\t")
          .replace('\n', "\\n")
          .replace('\r', "\\r");
        cells.push(escaped);
      }
    }
    lines.push(cells.join(separator));
  }
  lines.join("\n")
}

fn format_value(val: &serde_json::Value, fmt: Option<&spec::InsertFormat>) -> String {
  let fmt = match fmt {
    Some(f) => f,
    None => {
      return match val {
        serde_json::Value::String(s) => s.clone(),
        serde_json::Value::Null => String::new(),
        _ => val.to_string(),
      };
    }
  };
  match fmt {
    spec::InsertFormat::Text => match val {
      serde_json::Value::String(s) => s.clone(),
      serde_json::Value::Null => String::new(),
      _ => val.to_string(),
    },
    spec::InsertFormat::Json => {
      serde_json::to_string_pretty(val).unwrap_or_else(|_| val.to_string())
    }
    spec::InsertFormat::Yaml => serde_yaml::to_string(val)
      .map(|s| s.trim().to_string())
      .unwrap_or_else(|_| val.to_string()),
    spec::InsertFormat::Toon => toon_format::encode(val, &toon_format::EncodeOptions::default())
      .unwrap_or_else(|_| val.to_string()),
    spec::InsertFormat::Csv | spec::InsertFormat::Tsv => format_table(val, fmt),
  }
}

fn render_body(
  pieces: Option<&Vec<spec::BodyPiece>>,
  val: &serde_json::Value,
  snippets: &std::collections::HashMap<String, spec::Snippet>,
) -> String {
  let pieces = match pieces {
    Some(p) => p,
    None => return String::new(),
  };
  let mut result = String::new();
  for piece in pieces {
    match piece {
      spec::BodyPiece::KindText(p) => {
        result.push_str(&p.text);
      }
      spec::BodyPiece::KindInsertVal(p) => {
        let v = evaluate(&p.val, val);
        let formatted = format_value(&v, Some(&p.format));
        result.push_str(&indent(&formatted, &p.indent));
      }
      spec::BodyPiece::KindInsertSnippet(p) => {
        let snippet = snippets
          .get(&p.snippet)
          .unwrap_or_else(|| panic!("Snippet not found: {}", p.snippet));
        let rendered = render_snippet(snippet, val, snippets);
        result.push_str(&indent(&rendered, &p.indent));
      }
    }
  }
  result
}

fn render_snippet(
  snippet: &spec::Snippet,
  val: &serde_json::Value,
  snippets: &std::collections::HashMap<String, spec::Snippet>,
) -> String {
  match snippet {
    spec::Snippet::KindSnippet(s) => render_body(Some(&s.body), val, snippets),
    spec::Snippet::KindSnippetIf(s) => {
      let eval_result = evaluate(&s.expression, val);
      let condition = match s.is {
        spec::Snippet_KindSnippetIf_Is::NotEmpty => match &eval_result {
          serde_json::Value::Array(a) => !a.is_empty(),
          serde_json::Value::Object(o) => !o.is_empty(),
          serde_json::Value::String(str) => !str.is_empty(),
          serde_json::Value::Null => false,
          _ => true,
        },
        spec::Snippet_KindSnippetIf_Is::NotNull => !eval_result.is_null(),
        spec::Snippet_KindSnippetIf_Is::True => match &eval_result {
          serde_json::Value::Bool(b) => *b,
          serde_json::Value::String(str) => !str.is_empty(),
          serde_json::Value::Number(n) => n.as_f64().map_or(false, |num| num != 0.0),
          serde_json::Value::Null => false,
          _ => true,
        },
      };
      if condition {
        render_body(Some(&s.then), val, snippets)
      } else {
        render_body(Some(&s.else_), val, snippets)
      }
    }
    spec::Snippet::KindSnippetSwitch(s) => {
      let switch_val = evaluate(&s.expression, val);
      let switch_key = match &switch_val {
        serde_json::Value::Bool(b) => b.to_string(),
        serde_json::Value::String(str) => str.clone(),
        serde_json::Value::Number(n) => n.to_string(),
        _ => switch_val.to_string(),
      };
      let branch = s
        .branches
        .get(&switch_key)
        .or_else(|| s.branches.get("default"));
      render_body(branch, val, snippets)
    }
  }
}

fn render_examples(
  examples: Option<&Vec<spec::FewShotExample>>,
  user_body: Option<&Vec<spec::BodyPiece>>,
  template: &spec::Template,
) -> Vec<FewShotExample> {
  let examples = match examples {
    Some(e) => e,
    None => return Vec::new(),
  };
  let mut result = Vec::new();
  for example in examples {
    let rendered_user = render_body(user_body, &example.input, &template.snippets);
    let mut intermediate_steps = Vec::new();
    for step in &example.intermediate_steps {
      let mut tool_calls = Vec::new();
      for call in &step.tool_calls {
        let stringified_input = serde_json::to_string(&call.input).unwrap_or_default();
        let stringified_output = match &call.output {
          serde_json::Value::String(s) => s.clone(),
          other => serde_json::to_string(other).unwrap_or_default(),
        };
        tool_calls.push(ToolCallExample {
          call_id: call.call_id.clone(),
          tool_id: call.tool_id.clone(),
          tool_name: call.tool_name.clone(),
          stringified_input,
          stringified_output,
        });
      }
      intermediate_steps.push(IntermediateStepExample { tool_calls });
    }
    let response_str = match &example.output {
      serde_json::Value::String(s) => s.clone(),
      other => match template.output_format {
        spec::OutputFormat::Json => serde_json::to_string_pretty(other).unwrap_or_default(),
        spec::OutputFormat::Text => other.to_string(),
      },
    };
    result.push(FewShotExample {
      user_message: rendered_user,
      intermediate_steps,
      response: response_str,
    });
  }
  result
}

fn do_render<Input: serde::Serialize, Output, ToolExecutor: ?Sized>(
  spec: &spec::Templates,
  template_id_str: &str,
  input: &Input,
  execute_tool_call: Option<ExecuteToolCallFn<ToolExecutor>>,
) -> Prompt<Output, ToolExecutor> {
  let template = spec
    .templates
    .get(template_id_str)
    .unwrap_or_else(|| panic!("Template not found: {}", template_id_str));
  let input_val = serde_json::to_value(input).expect("Failed to serialize input");

  let (template_content, default_content) = match &template.contents {
    spec::TemplateContents::KindNoVariants(c) => (&c.content, None),
    spec::TemplateContents::KindVariants(v) => {
      let variant = input_val
        .get("variant")
        .and_then(|v| v.as_str())
        .expect("Input for template with variants must contain 'variant'");
      let variant_content = v
        .variants
        .get(variant)
        .unwrap_or_else(|| panic!("Variant not found: {}", variant));
      (variant_content, Some(&v.default_content))
    }
  };

  let system_body = template_content
    .system
    .as_ref()
    .or_else(|| default_content.and_then(|d| d.system.as_ref()));
  let user_body = template_content
    .user
    .as_ref()
    .or_else(|| default_content.and_then(|d| d.user.as_ref()));
  let examples_data = template_content
    .examples
    .as_ref()
    .or_else(|| default_content.and_then(|d| d.examples.as_ref()));

  let system_message = render_body(system_body, &input_val, &template.snippets);
  let user_message = render_body(user_body, &input_val, &template.snippets);
  let examples = render_examples(examples_data, user_body, template);

  let mut tools = std::collections::HashMap::new();
  for t in &template.tools {
    if let Some(tool_spec) = spec.tools.get(&t.id) {
      let stringified_schema = tool_spec
        .input_json_schema
        .as_ref()
        .map(|s| serde_json::to_string_pretty(s).unwrap_or_default())
        .unwrap_or_else(|| "{}".to_string());
      tools.insert(
        t.name.clone(),
        Tool {
          id: tool_spec.id.clone(),
          name: tool_spec.name.clone(),
          description: tool_spec.description.clone(),
          stringified_input_json_schema: stringified_schema,
        },
      );
    }
  }

  let output_format = match template.output_format {
    spec::OutputFormat::Json => {
      let schema_str = template
        .output_json_schema
        .as_ref()
        .map(|s| serde_json::to_string_pretty(s).unwrap_or_default())
        .unwrap_or_else(|| "{}".to_string());
      OutputFormat::Json(JsonOutputFormat {
        stringified_json_schema: schema_str,
      })
    }
    spec::OutputFormat::Text => OutputFormat::Text(TextOutputFormat),
  };

  let meta_val = template_content
    .meta
    .as_ref()
    .or_else(|| default_content.and_then(|d| d.meta.as_ref()));
  let meta: Meta = match meta_val {
    Some(m) => serde_json::from_value(m.clone()).unwrap_or_else(|_| {
      serde_json::from_str("null").unwrap_or_else(|_| serde_json::from_str("{}").unwrap())
    }),
    None => {
      serde_json::from_str("null").unwrap_or_else(|_| serde_json::from_str("{}").unwrap())
    }
  };

  let template_id = TemplateId::from_id(template_id_str)
    .unwrap_or_else(|| panic!("Unknown template ID: {}", template_id_str));

  Prompt {
    meta,
    system_message,
    user_message,
    examples,
    tools,
    output_format,
    template_id,
    execute_tool_call,
    _phantom: std::marker::PhantomData,
  }
}

fn do_parse_response<Output: serde::de::DeserializeOwned>(
  output_format: &OutputFormat,
  template_id: &TemplateId,
  response: &str,
) -> Result<Output, Box<dyn std::error::Error + Send + Sync>> {
  match output_format {
    OutputFormat::Json(_) => {
      let mut cleaned = response.trim();
      if cleaned.starts_with("```") {
        if let Some(stripped) = cleaned.strip_prefix("```json") {
          cleaned = stripped;
        } else if let Some(stripped) = cleaned.strip_prefix("```") {
          cleaned = stripped;
        }
        if let Some(stripped) = cleaned.strip_suffix("```") {
          cleaned = stripped;
        }
        cleaned = cleaned.trim();
      }
      serde_json::from_str::<Output>(cleaned)
        .map_err(|e| format!("Template '{}': {}", template_id, e).into())
    }
    OutputFormat::Text(_) => {
      serde_json::from_value::<Output>(serde_json::Value::String(response.to_string()))
        .map_err(|e| format!("Template '{}': {}", template_id, e).into())
    }
  }
}
